    ["<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Cognitive Limit</>\nDivinity Level Limit has reached the season cap: <Yellow>%s Level</>"] = "<img id=\"Tips\" width=\"30\" height=\"46\"/><Title>Когнитивное ограничение</>\nПредел божественного уровня достиг верхнего предела этого сезона: <Yellow>%slevel</>",
